policy "s3_bucket_hardening" {
  enforcement_level = "hard-mandatory"
  main = rule {
    all aws_s3_bucket.resources as _, instances {
      all instances as _, r {
        r.server_side_encryption_configuration is not empty
        r.versioning.enabled is true
        r.public_access_block.block_public_acls is true
        r.public_access_block.block_public_policy is true
        r.public_access_block.ignore_public_acls is true
        r.public_access_block.restrict_public_buckets is true
        r.policy contains "s3:x-amz-server-side-encryption"
      }
    }
  }
}

